package com.arms.game.combat;

/**
 * Combat Results Table. Columns are odds ratios from 1/2 (index 0) up to 6/1 (index 6); rows are the sum of the
 * two white dice (2-12). A result is the Hit Points taken by each side.
 *
 * INFERRED: the real grid is not in the rulebook photos, so the results are generated by formula to follow the
 * same shape (better odds hurt the defender more and the attacker less). Replace {@link #lookup} with the real
 * table when we have it.
 */
public final class CRT {

    public static final int COLUMNS = 7;

    public record Result(int attackerHp, int defenderHp) {
    }

    private CRT() {
    }

    public static Result lookup(int columnIndex, int diceSum) {
        if (columnIndex < 0 || columnIndex >= COLUMNS) {
            throw new IllegalArgumentException("No CRT column " + columnIndex);
        }
        if (diceSum < 2 || diceSum > 12) {
            throw new IllegalArgumentException("Two dice sum to 2-12, not " + diceSum);
        }
        int defenderHp = Math.max(0, (diceSum + 2 * columnIndex - 8) / 2);
        int attackerHp = Math.max(0, (16 - diceSum - 2 * columnIndex) / 3);
        return new Result(attackerHp, defenderHp);
    }
}
